run_ct15.ps1.content:
param([Parameter(ValueFromRemainingArguments=$true)][string[]]$TrialArguments)
$ErrorActionPreference = 'Stop'
$ct15Container = (docker inspect caliburn-q019-postgres | ConvertFrom-Json)[0]
if ($LASTEXITCODE -ne 0 -or $ct15Container.State.Status -ne 'running') { throw 'Dedicated test database is not running' }
$ct15Settings = @{}
foreach ($ct15Entry in $ct15Container.Config.Env) {
    $ct15Pair = $ct15Entry.Split('=', 2)
    $ct15Settings[$ct15Pair[0]] = $ct15Pair[1]
}
if ($ct15Settings.POSTGRES_DB -ne 'q019_agent_test' -or $ct15Settings.POSTGRES_USER -ne 'q019') { throw 'Unexpected database identity' }
if ($ct15Container.NetworkSettings.Ports.'5432/tcp'[0].HostPort -ne '55433') { throw 'Unexpected port' }
$env:Q019_TEST_DATABASE_URL = 'postgresql://q019:' + [uri]::EscapeDataString($ct15Settings.POSTGRES_PASSWORD) + '@127.0.0.1:55433/q019_agent_test?connect_timeout=5'
$env:PYTHONUTF8 = '1'
$env:PYTHONPATH = 'src'
try {
    if ($TrialArguments[0] -eq 'tests') {
        & .venv/Scripts/python.exe -m pytest -q --tb=short --basetemp=.test-tmp/ct15-pg-timeout-verified
    } else {
        & .venv/Scripts/python.exe .test-tmp/ct15_full.py @TrialArguments
    }
    $ct15Exit = $LASTEXITCODE
} finally {
    Remove-Item Env:Q019_TEST_DATABASE_URL -ErrorAction SilentlyContinue
    $ct15Settings.Clear()
}
exit $ct15Exit
